// Tailored record sections for events, tasks, Teams threads and finance records. Display
// only, from the object page payload: which section a fact belongs to comes from the
// schema (record-kinds.json, generated by tools/gen_record_kinds.py from the ontology
// schema), never from a record's name. A fact the server did not send (a finance-marked
// amount for a reader without finance access) is simply not there, and the section says
// so in plain words; nothing is guessed or filled in.

import kinds from "./record-kinds.json";
import { formatDateTime, objectHref, plural, readable, recordLabel, typeLabel } from "./format";
import { factMap, factValue, groupRelated, moneyText, type RecordFact } from "./record";
import type { ObjectPage, ObjectRef } from "./types";

type PropRole = "money" | "aging" | "person" | "party" | "account" | "status" | "text" | "when" | "other";
interface KindEntry {
  role: string;
  family?: "event" | "task" | "thread" | "finance";
  props?: Record<string, { role: PropRole; marked?: string[] }>;
}
const TYPES = (kinds as { types: Record<string, KindEntry> }).types;

export type Family = NonNullable<KindEntry["family"]>;

export function familyOf(type: string): Family | null {
  return TYPES[type]?.family ?? null;
}

/** The role the schema gives a record type (party, document, finance, event, task, ...). */
export function roleOf(type: string): string {
  return TYPES[type]?.role ?? "record";
}

export interface KindRow {
  label: string;
  value: string;
  href?: string;
  at?: string | null;
  count?: number;
}
export interface KindSection {
  id: string;
  title: string;
  rows: KindRow[];
  /** Said in plain words when the section has no rows. */
  empty: string;
}

const FINANCE_HIDDEN = "No amounts are shown to you. Amounts on finance records are visible only to readers with finance access.";

/** A people value ("A; B", a JSON list of names or {name}/{emailAddress:{name}}) as names. */
export function peopleIn(value: string): string[] {
  const v = readable(value).trim();
  if (!v) return [];
  if (v.startsWith("[") || v.startsWith("{")) {
    try {
      const out: string[] = [];
      const walk = (x: unknown): void => {
        if (typeof x === "string") out.push(x);
        else if (Array.isArray(x)) x.forEach(walk);
        else if (x && typeof x === "object") {
          const o = x as Record<string, unknown>;
          const n = o.name ?? o.displayName ?? o.display_name ?? (o.emailAddress as Record<string, unknown> | undefined)?.name ?? (o.emailAddress as Record<string, unknown> | undefined)?.address ?? o.address ?? o.email;
          if (typeof n === "string") out.push(n);
          else if (n && typeof n === "object") walk(n);
        }
      };
      walk(JSON.parse(v));
      return [...new Set(out.map((s) => s.trim()).filter(Boolean))];
    } catch {
      /* not JSON: read it as text */
    }
  }
  return [...new Set(v.split(/\s*[;,]\s*/).map((s) => s.trim()).filter(Boolean))];
}

function timeText(v: string): string {
  return /^\d{4}-\d{2}-\d{2}T/.test(v) ? formatDateTime(v) : factValue(v);
}

/** The related records whose schema role is one of `roles`, as rows (one per record, repeats counted). */
function relatedRows(refs: ObjectRef[], keep: (r: ObjectRef) => boolean): KindRow[] {
  const rows: KindRow[] = [];
  for (const g of groupRelated(refs.filter(keep))) {
    for (const it of g.items) rows.push({ label: g.label, value: recordLabel(it.type, readable(it.label)), href: it.open_url || objectHref(it.type, it.object_id), count: it.times > 1 ? it.times : undefined });
    if (g.unnamed > 0) rows.push({ label: g.label, value: plural(g.unnamed, "unnamed record") });
  }
  return rows;
}

function personRows(label: string, names: string[], refs: ObjectRef[]): KindRow[] {
  const byName = new Map<string, ObjectRef>();
  for (const r of refs) if (["person", "party"].includes(roleOf(r.type))) byName.set(readable(r.label).trim().toLowerCase(), r);
  return names.map((n) => {
    const hit = byName.get(n.toLowerCase());
    return { label, value: n, href: hit ? hit.open_url || objectHref(hit.type, hit.object_id) : undefined };
  });
}

function history(obj: ObjectPage, max = 12): KindRow[] {
  return [...(obj.timeline ?? [])]
    .sort((a, b) => (b.at ?? "").localeCompare(a.at ?? ""))
    .slice(0, max)
    .map((e) => ({ label: e.at ? formatDateTime(e.at) : "Undated", value: readable(e.title), at: e.at }));
}

/** The tailored sections for this record's type, or null for a type with none (it keeps the generic page). */
export function kindSections(obj: ObjectPage): KindSection[] | null {
  const entry = TYPES[obj.type];
  if (!entry?.family || !entry.props) return null;
  const f = factMap(obj.facts);
  const refs = obj.related ?? [];
  const currency = f.get("currency")?.value;
  const byRole = (...roles: PropRole[]): { name: string; fact: RecordFact; role: PropRole }[] =>
    Object.entries(entry.props!)
      .filter(([, p]) => roles.includes(p.role))
      .flatMap(([name, p]) => {
        const fact = f.get(name);
        return fact && fact.value !== "" ? [{ name, fact, role: p.role }] : [];
      });
  const plain = (...roles: PropRole[]): KindRow[] =>
    byRole(...roles).map(({ fact, role }) => ({ label: fact.label, value: role === "money" ? (moneyText(fact.value, currency) ?? fact.value) : role === "when" || role === "aging" ? timeText(fact.value) : readable(fact.value) }));
  const people = (): KindRow[] => {
    const rows = byRole("person").flatMap(({ fact }) => personRows(fact.label, peopleIn(fact.value), refs));
    const seen = new Set(rows.map((r) => r.value.toLowerCase()));
    // people the page found for the record, not already listed
    for (const p of obj.people ?? []) if (!seen.has(p.name.toLowerCase())) rows.push({ label: p.role, value: p.name });
    return rows;
  };
  const role = (r: string) => (x: ObjectRef) => roleOf(x.type) === r;
  const out: KindSection[] = [];

  switch (entry.family) {
    case "event": {
      const att = people();
      out.push({ id: "when", title: "When and where", rows: plain("when", "status"), empty: "No time or place is on record for this event." });
      out.push({ id: "attendees", title: "Attendees", rows: att, empty: "No attendees are on record for this event." });
      out.push({ id: "agenda", title: "Agenda and notes", rows: plain("text"), empty: "No agenda or notes are on record, and the Workbench writes none in their place." });
      out.push({ id: "parties", title: "Customers and suppliers", rows: relatedRows(refs, role("party")), empty: "No customer or supplier is linked to this event." });
      out.push({ id: "records", title: "Related orders and records", rows: relatedRows(refs, (x) => !["party", "person", "event"].includes(roleOf(x.type))), empty: "No orders or other records are linked to this event." });
      out.push({ id: "copies", title: "Calendar copies and transcripts", rows: relatedRows(refs, role("event")), empty: "No other copy or transcript of this event is on record." });
      break;
    }
    case "task": {
      out.push({ id: "status", title: "Status", rows: plain("status"), empty: "No status is on record for this item." });
      out.push({ id: "who", title: "Assignee and owners", rows: people(), empty: "No one is named on this item." });
      out.push({ id: "dates", title: "Due and dates", rows: plain("when"), empty: "No due date or other date is on record." });
      out.push({ id: "text", title: "Description", rows: plain("text"), empty: "No description is on record." });
      out.push({ id: "history", title: "History", rows: history(obj), empty: "No changes are on record for this item yet." });
      out.push({ id: "approvals", title: "Approvals", rows: relatedRows(refs, (x) => x.type === "MCApproval"), empty: "No approval has been asked for on this item." });
      out.push({ id: "records", title: "Related records", rows: relatedRows(refs, (x) => x.type !== "MCApproval" && roleOf(x.type) !== "person"), empty: "No other records are linked to this item." });
      break;
    }
    case "thread": {
      const msgs = (obj.linked ?? []).filter((l) => l.kind === "teams");
      out.push({ id: "details", title: "Thread", rows: [...plain("text", "status", "when"), ...msgs.slice(0, 10).map((m) => ({ label: m.at ? formatDateTime(m.at) : "Message", value: readable(m.label), at: m.at }))], empty: "No messages from this thread are on record for you." });
      out.push({ id: "participants", title: "Participants", rows: people(), empty: "Participants of this thread are not on record, or you may not see them." });
      out.push({ id: "mentioned", title: "Mentioned records", rows: relatedRows(refs, (x) => roleOf(x.type) !== "person" && familyOf(x.type) !== "thread"), empty: "No order or other record is linked to this thread." });
      break;
    }
    case "finance": {
      const money = plain("money");
      out.push({ id: "amounts", title: "Amounts", rows: money, empty: FINANCE_HIDDEN });
      out.push({ id: "account", title: "Account", rows: [...plain("account"), ...relatedRows(refs, (x) => x.type === "GlAccount")], empty: "No account is on record for this entry." });
      out.push({
        id: "counterparty",
        title: "Counterparty",
        rows: [...plain("party"), ...relatedRows(refs, role("party"))],
        empty: "No customer or supplier is linked to this record.",
      });
      if (byRole("aging").length > 0 || /^Aged/.test(obj.type)) out.push({ id: "aging", title: "Aging", rows: plain("aging"), empty: "No aging is on record for you." });
      out.push({ id: "documents", title: "Related documents", rows: relatedRows(refs, (x) => ["document", "finance"].includes(roleOf(x.type)) && x.type !== obj.type), empty: "No invoice, payment or other document is linked to this record." });
      break;
    }
  }
  return out;
}

/** The title a section group takes on the page, e.g. for an accessible name. */
export function kindTitle(type: string): string {
  return typeLabel(type);
}
